import { ref, nextTick } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import DockerNetworks from '@/components/Network/DockerNetworks.vue';

// 弹出框状态

export default {
  __name: 'AddContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const networksRef = ref(null);
    const NetworkList = ref([]);

    // 容器数据
    const container = ref({
      image: '',
      name: '',
      networks: []
    });

    // 用于父组件调用刷新列表
    const updateContainerList = ref(null);

    // 打开弹窗时调用网络组件获取网络列表
    const openDialog = async () => {
      container.value = {
        image: '',
        name: '',
        networks: []
      };
      dialogVisible.value = true;
      await nextTick(); // 等待 DockerNetworks 组件挂载
      if (networksRef.value) {
        await networksRef.value.fetchNetworks();
        NetworkList.value = Object.keys(networksRef.value.networks || {});
      } else {
        console.error('DockerNetworks 组件尚未挂载');
      }
    };

    // 提交容器创建
    const submitAdd = async () => {
      try {
        await axios.post('http://localhost:8081/container/create', container.value);
        dialogVisible.value = false;
        ElMessage.success('容器添加成功');

        // 调用父组件的方法刷新容器列表
        if (updateContainerList.value) {
          updateContainerList.value.fetchContainers();
        }
      } catch (error) {
        console.error('Error creating container:', error.response || error);
        ElMessage.error('容器添加失败');
      }
    };

    // 暴露方法供父组件调用刷新容器列表
    __expose({
      openDialog,
      updateContainerList
    });
    const __returned__ = {
      dialogVisible,
      networksRef,
      NetworkList,
      container,
      updateContainerList,
      openDialog,
      submitAdd,
      ref,
      nextTick,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerNetworks
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
